.version 7.0
.target sm_80
.address_size 64

.visible .entry batched_gemm (
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 batch,
    .param .u32 m,
    .param .u32 k,
    .param .u32 n
)
{
    // -----------------------------------------------------------------
    // Load kernel parameters
    // -----------------------------------------------------------------
    .reg .u64 %A, %B, %C;
    .reg .u32 %batch, %m, %k, %n;
    ld.param.u64 %A, [A_ptr];
    ld.param.u64 %B, [B_ptr];
    ld.param.u64 %C, [C_ptr];
    ld.param.u32 %batch, [batch];
    ld.param.u32 %m, [m];
    ld.param.u32 %k, [k];
    ld.param.u32 %n, [n];

    // -----------------------------------------------------------------
    // Thread / block indices
    // -----------------------------------------------------------------
    .reg .u32 %tid_x, %tid_y, %blk_x, %blk_y, %blk_z;
    mov.u32 %tid_x, %tid.x;
    mov.u32 %tid_y, %tid.y;
    mov.u32 %blk_x, %ctaid.x;
    mov.u32 %blk_y, %ctaid.y;
    mov.u32 %blk_z, %ctaid.z;

