    // j = blk_x * blockDim.x + tid_x
    .reg .u32 %i, %j, %b;
    mad.lo.u32 %i, %blk_y, %ntid.y, %tid_y;
    mad.lo.u32 %j, %blk_x, %ntid.x, %tid_x;
    mov.u32 %b, %blk_z;          // batch index

    // -----------------------------------------------------------------
    // Bounds check
    // -----------------------------------------------------------------
    .reg .pred %out_of_bounds;
    setp.ge.u32 %out_of_bounds, %i, %m;
    setp.ge.u32 %p, %j, %n;
    or.pred %out_of_bounds, %out_of_bounds, %p;
    @%out_of_bounds bra DONE;

    // -----------------------------------------------------------------
    // Accumulator (FP32)
    // -----------------------------------------------------------------
    .reg .f32 %acc;
    mov.f32 %acc, 0.0;

    // -----------------------------------------------------------------
    // Loop over K dimension
    // -----------------------------------------------------------------
    .reg .u32 %p_idx;
    mov.u32 %p_idx, 0;

