    mul.wide.u32 %tmp2, %tmp1, %k;       // (b*m + i)*k
    add.u64 %idxA, %tmp2, %p_idx;        // + p
    shl.b64 %addrA, %idxA, 1;            // * sizeof(half) = 2
    add.u64 %addrA, %A, %addrA;

