    // idxB = ((b*k + p) * n) + j
    .reg .u64 %tmp3, %tmp4, %tmp5, %idxB, %addrB;
    mul.wide.u32 %tmp3, %b, %k;          // b*k
    add.u64 %tmp4, %tmp3, %p_idx;        // b*k + p
    mul.wide.u32 %tmp5, %tmp4, %n;       // * n
    add.u64 %idxB, %tmp5, %j;            // + j
    shl.b64 %addrB, %idxB, 1;            // *2
    add.u64 %addrB, %B, %addrB;

