    .reg .f16 %b_f16;
    .reg .f32 %b_f32;
    ld.global.nc.f16 %b_f16, [%addrB];
    cvt.f32.f16 %b_f32, %b_f16;

    // FP32 multiply‑accumulate
    fma.rn.f32 %acc, %a_f32, %b_f32, %acc;

    // Increment p
    add.u32 %p_idx, %p_idx, 1;
    bra LOOP_K;

